        [Fact(DisplayName = "trees > a marked tree is chopped for wood only, stays marked, and grows back")]
        public void T002_a_marked_tree_is_chopped_for_wood_only_stays_marked_and_grow()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 3, map = ["s..Y", "...."] });
            Js.NN(Js.Get(state.survivors, 0)).priorities = new(JobTypes.NO_JOBS) { ["scavenge"] = 3 };
            var tree = Js.NN(Js.Get(state.furniture, 0));
            expect(tree.loot).toBe(FurnitureMod.TREE_WOOD);
            expect(Commands.applyCommand(state, new Command { type = "designateScavenge", x = Js.I(3), y = Js.I(0) })).toEqual(Js.Obj(("ok", (object?)(true)), ("changed", (object?)(true))));
            runUntil(state, (_) => tree.loot == 0);
            expect(state.items.map((i) => i.kind)).toEqual(Js.Filled<string>(FurnitureMod.TREE_WOOD, "wood"));
            expect(Js.NN(Js.Get(state.survivors, 0)).note).toBe("chopped wood from (3, 0), 0 left");
            expect(tree.scavenge).toBe(true);
            state.tick = Js.I(FurnitureMod.TREE_REGROW_TICKS);
            Tick.tick(state);
            expect(tree.loot).toBe(1);
            runUntil(state, (_) => state.items.filter((i) => i.kind == "wood").length == (FurnitureMod.TREE_WOOD + 1));
        }

        [Fact(DisplayName = "trees > unmarked trees are left alone; Cancel unmarks")]
        public void T003_unmarked_trees_are_left_alone_Cancel_unmarks()
        {
