            Commands.applyCommand(state, new Command { type = "designateScavenge", x = Js.I(3), y = Js.I(0) });
            expect(Commands.applyCommand(state, new Command { type = "cancelDesignation", x = Js.I(3), y = Js.I(0) })).toEqual(Js.Obj(("ok", (object?)(true)), ("changed", (object?)(true))));
