    /// <summary>zombie groups</summary>
    public class D004_zombie_groups
    {

        public static List<double> arrivals(double night)
        {
            List<double> @out = [];
            for (var t = (night - 1) * Time.DAY_LENGTH; t < ((night + 1) * Time.DAY_LENGTH); t++)
            {
                if ((Time.nightNumber(t) == night) && (Zombies.spawnsAt(t) > 0))
                {
                    @out.push(Zombies.spawnsAt(t));
                }
            }
            return @out;
        }

        [Fact(DisplayName = "zombie groups > come singly for three nights, then in pairs, then threes; the total per night is unchanged")]
        public void T005_come_singly_for_three_nights_then_in_pairs_then_threes_the_t()
        {
            expect(new List<double> { 1, 3, 4, 6, 7 }.map((__f0) => Zombies.groupSize(__f0))).toEqual(Js.Arr([1, 1, 2, 2, 3]));
            expect(arrivals(1)).toEqual(Js.Arr([1, 1]));
            expect(arrivals(3)).toEqual(Js.Arr([1, 1, 1, 1]));
            expect(arrivals(4)).toEqual(Js.Arr([2, 2, 1]));
            expect(arrivals(7)).toEqual(Js.Arr([3, 3, 2]));
            foreach (var n in Js.Iter((List<double>)[1, 4, 7, 10]))
            {
                expect(arrivals(n).reduce((a, b) => a + b, 0.0)).toBe(Zombies.zombiesForNight(n));
            }
        }

        [Fact(DisplayName = "zombie groups > a group arrives together on neighbouring outdoor tiles")]
        public void T006_a_group_arrives_together_on_neighbouring_outdoor_tiles()
        {
            var map = Js.ArrayFrom(21, (int y) => (y == 10) ? $"{Js.Str(".".repeat(20))}s{Js.Str(".".repeat(20))}" : ".".repeat(41));
            var state = ScenarioMod.loadScenario(new Scenario { seed = 5, map = map });
            Js.NN(Js.Get(state.survivors, 0)).priorities = new(JobTypes.NO_JOBS) {  };
            var first = Js.NN(Js.ArrayFrom(2 * Time.DAY_LENGTH, (int i) => (3 * Time.DAY_LENGTH) + i).find((t) => Zombies.spawnsAt(t) == 2));
            state.tick = Js.I(first);
            Tick.tick(state);
            expect(state.zombies).toHaveLength(2);
            var (a, b) = state.zombies;
            expect(JsMath.abs(Js.NN(a).pos.x - Js.NN(b).pos.x) + JsMath.abs(Js.NN(a).pos.y - Js.NN(b).pos.y)).toBe(1);
            expect(Js.NN(state.events.at(-1)).message).toMatch(new JsRegExp("^A group of 2 zombies appeared at", ""));
        }
    }

